\set ON_ERROR_STOP on
\set target_email 'qacer6973@gmail.com'

-- WaveStack browser-library import for Oracle PostgreSQL.
-- This replaces the target account's server-side favorites, recent list,
-- and playlists with the contents of the supplied browser backup.
-- It does not import wavestack:song-cache because Drive sync owns the catalog.

BEGIN;

CREATE TEMP TABLE _wavestack_import_payload (
    data jsonb NOT NULL
) ON COMMIT DROP;

INSERT INTO _wavestack_import_payload(data)
VALUES (
    convert_from(
        decode('', 'base64'),
        'UTF8'
    )::jsonb
);

SELECT set_config(
    'wavestack.import_email',
    :'target_email',
    true
);

DO $wavestack_import$
DECLARE
    v_user_id uuid;
    v_data jsonb;
    v_favorite_count integer;
    v_recent_count integer;
    v_playlist_count integer;
    v_playlist_song_count integer;
BEGIN
    SELECT id
    INTO STRICT v_user_id
    FROM app_users
    WHERE lower(email) = lower(
        current_setting('wavestack.import_email')
    );

    SELECT data
    INTO STRICT v_data
    FROM _wavestack_import_payload;

    IF EXISTS (
        SELECT 1
        FROM app_user_playlists existing
        JOIN jsonb_array_elements(v_data->'playlists') imported
          ON existing.id = (imported->>'id')::uuid
        WHERE existing.user_id <> v_user_id
    ) THEN
        RAISE EXCEPTION
          'A backed-up playlist ID already belongs to another Oracle user.';
    END IF;

    -- Replace only this user's current server-side state.
    DELETE FROM app_favorites
    WHERE user_id = v_user_id;

    DELETE FROM app_listening_events
    WHERE user_id = v_user_id;

    DELETE FROM app_user_playlists
    WHERE user_id = v_user_id;

    -- The first item in the browser array is treated as the newest favorite.
    INSERT INTO app_favorites (
        user_id,
        song_id,
        created_at
    )
    SELECT
        v_user_id,
        item.song_id,
        clock_timestamp()
          - ((item.position - 1) * interval '1 second')
    FROM jsonb_array_elements_text(v_data->'favorites')
         WITH ORDINALITY AS item(song_id, position)
    ON CONFLICT (user_id, song_id) DO UPDATE
    SET created_at = EXCLUDED.created_at;

    -- Browser recent data contains ordering, not original play timestamps
    -- or play counts. Create one synthetic event per item to preserve order.
    INSERT INTO app_listening_events (
        user_id,
        song_id,
        artist_name,
        title,
        duration_seconds,
        completed_play_ratio,
        started_at
    )
    SELECT
        v_user_id,
        item.song_id,
        COALESCE(track.artist_name, ''),
        COALESCE(track.title, ''),
        COALESCE(track.duration_seconds, 0),
        0,
        clock_timestamp()
          - ((item.position - 1) * interval '1 minute')
    FROM jsonb_array_elements_text(v_data->'recent')
         WITH ORDINALITY AS item(song_id, position)
    LEFT JOIN drive_tracks track
      ON track.id = item.song_id;

    INSERT INTO app_user_playlists (
        id,
        user_id,
        name,
        created_at,
        updated_at
    )
    SELECT
        (playlist->>'id')::uuid,
        v_user_id,
        COALESCE(NULLIF(playlist->>'name', ''), 'Imported playlist'),
        COALESCE(
            NULLIF(playlist->>'createdAt', '')::timestamptz,
            clock_timestamp()
        ),
        COALESCE(
            NULLIF(playlist->>'updatedAt', '')::timestamptz,
            clock_timestamp()
        )
    FROM jsonb_array_elements(v_data->'playlists') AS playlist;

    INSERT INTO app_user_playlist_songs (
        playlist_id,
        song_id,
        position,
        added_at
    )
    SELECT
        (playlist->>'id')::uuid,
        song.song_id,
        (song.position - 1)::integer,
        clock_timestamp()
          + ((song.position - 1) * interval '1 millisecond')
    FROM jsonb_array_elements(v_data->'playlists') AS playlist
    CROSS JOIN LATERAL
         jsonb_array_elements_text(playlist->'songIds')
         WITH ORDINALITY AS song(song_id, position);

    SELECT count(*) INTO v_favorite_count
    FROM app_favorites
    WHERE user_id = v_user_id;

    SELECT count(DISTINCT song_id) INTO v_recent_count
    FROM app_listening_events
    WHERE user_id = v_user_id;

    SELECT count(*) INTO v_playlist_count
    FROM app_user_playlists
    WHERE user_id = v_user_id;

    SELECT count(*) INTO v_playlist_song_count
    FROM app_user_playlist_songs songs
    JOIN app_user_playlists playlists
      ON playlists.id = songs.playlist_id
    WHERE playlists.user_id = v_user_id;

    RAISE NOTICE
      'Imported for %: % favorites, % recent tracks, % playlists, % playlist songs.',
      current_setting('wavestack.import_email'),
      v_favorite_count,
      v_recent_count,
      v_playlist_count,
      v_playlist_song_count;
END
$wavestack_import$;

COMMIT;

-- Verification summary.
SELECT
    users.email,
    (
        SELECT count(*)
        FROM app_favorites favorites
        WHERE favorites.user_id = users.id
    ) AS favorites,
    (
        SELECT count(DISTINCT events.song_id)
        FROM app_listening_events events
        WHERE events.user_id = users.id
    ) AS recent_tracks,
    (
        SELECT count(*)
        FROM app_user_playlists playlists
        WHERE playlists.user_id = users.id
    ) AS playlists,
    (
        SELECT count(*)
        FROM app_user_playlist_songs songs
        JOIN app_user_playlists playlists
          ON playlists.id = songs.playlist_id
        WHERE playlists.user_id = users.id
    ) AS playlist_songs
FROM app_users users
WHERE lower(users.email) = lower(:'target_email');
